#include <vector>
#include <algorithm>

class Solution {
public:
    /**
     * 方法：雙指標交換
     * 時間複雜度: O(n)
     * 空間複雜度: O(1)
     */
    void reverseString(std::vector<char>& s) {
        int left = 0;
        int right = s.size() - 1;

        while (left < right) {
            // 交換左右字符
            std::swap(s[left], s[right]);
            // 指標向中間移動
            left++;
            right--;
        }
    }

    /**
     * 方法：使用標準庫
     */
    void reverseString_stl(std::vector<char>& s) {
        std::reverse(s.begin(), s.end());
    }
};

