class Solution {
    /**
     * 方法：雙指標交換
     * 時間複雜度: O(n)
     * 空間複雜度: O(1)
     */
    public void reverseString(char[] s) {
        int left = 0;
        int right = s.length - 1;

        while (left < right) {
            // 交換左右字符
            char temp = s[left];
            s[left] = s[right];
            s[right] = temp;

            // 指標向中間移動
            left++;
            right--;
        }
    }
}

