// 雙指標：頭尾交換，往中間靠攏
// 時間複雜度: O(n)，空間複雜度: O(1)
void reverseString(char* s, int sSize) {
    int left = 0, right = sSize - 1;
    while (left < right) {
        char tmp = s[left];
        s[left++] = s[right];
        s[right--] = tmp;
    }
}

